import{_ as p,C as i,o as m,c as h,j as t,a as d,E as o,aj as a,w as r}from"./chunks/framework.Cf8CqEYQ.js";const y=JSON.parse('{"title":"AgentGateway 解耦设计：到底要求了什么","description":"一页讲清 AgentGateway 的两条解耦轴（客户端格式 ↔ AG-IR canonical ↔ provider 格式；DI 接口+构造注入+组合根）、七条不可违背的约束、DI 的真实代价，以及现状与缺口。","frontmatter":{"title":"AgentGateway 解耦设计：到底要求了什么","description":"一页讲清 AgentGateway 的两条解耦轴（客户端格式 ↔ AG-IR canonical ↔ provider 格式；DI 接口+构造注入+组合根）、七条不可违背的约束、DI 的真实代价，以及现状与缺口。","tags":["agentgateway","architecture","design","decoupling"],"date":"2026-11-16","layout":"doc","aside":false,"outline":false,"prev":false,"next":false},"headers":[],"relativePath":"artifacts/ag-decoupling-design.md","filePath":"artifacts/ag-decoupling-design.md"}'),u={name:"artifacts/ag-decoupling-design.md"};function S(b,e,P,v,G,T){const s=i("Badges"),n=i("StatGrid"),c=i("Callout"),I=i("SvgDiagram"),l=i("KeyValue"),g=i("Steps");return m(),h("div",null,[e[3]||(e[3]=t("h2",{id:"_0-·-证据分级-先看这条-全文通用",tabindex:"-1"},[d("0 · 证据分级（先看这条，全文通用） "),t("a",{class:"header-anchor",href:"#_0-·-证据分级-先看这条-全文通用","aria-label":'Permalink to "0 · 证据分级（先看这条，全文通用）"'},"​")],-1)),e[4]||(e[4]=t("p",null,"页面上每个结论都尽量标了来源级别。你没空读设计文档，但你应该知道哪条是我验过的、哪条只是我推断的。",-1)),o(s,{items:[{text:"【文档】docs/design 或 AGENTS.md 写明",tone:"blue"},{text:"【代码】仓库代码可直接验证",tone:"green"},{text:"【实测】有测试输出或审计报告支撑",tone:"green"},{text:"【推断】我的推理，未落纸，需你确认",tone:"amber"}]}),e[5]||(e[5]=t("blockquote",null,[t("p",null,[d("本文不修改仓库任何文件、不 commit。所有路径都是仓库相对路径；"),t("code",null,"~/ai-workspace/ag-serve.mjs"),d(" 这类仓库外文件用文字描述指代，不写绝对路径与任何真实密钥 / IP。")])],-1)),e[6]||(e[6]=t("hr",null,null,-1)),e[7]||(e[7]=t("h2",{id:"_1-·-一屏结论",tabindex:"-1"},[d("1 · 一屏结论 "),t("a",{class:"header-anchor",href:"#_1-·-一屏结论","aria-label":'Permalink to "1 · 一屏结论"'},"​")],-1)),o(n,{items:[{label:"解耦轴",value:"2 条"},{label:"Pipeline 阶段",value:"11（S0–S10）"},{label:"插件 hook",value:"5"},{label:"canonical 模态",value:"9"},{label:"组合根可选端口",value:"35"},{label:"已注册 adaptor",value:"2"}]}),e[8]||(e[8]=a("<p><strong>解耦换来了什么</strong>：加一种客户端格式 = 加一个 codec + 一张映射表 + 一组 round-trip 测试；加一家 provider = 加一条 access path + 一个 profile + 一行能力矩阵。两者都不碰别人的代码。【文档】<code>40-provider-adaptors.md</code> §1.0 的设计目标原文是「<strong>新增一个 adaptor 是机械活</strong>——照着注册机制、映射方法论、测试模板做，不需要重新发明任何东西」。</p><p><strong>代价是什么</strong>（四条，都是实的）：</p><ol><li>每个请求都完整走一遍 canonical。实测量级是「JSON parse + 对象映射 + stringify」，典型对话请求<strong>亚毫秒到几毫秒</strong>，相对 LLM 推理可忽略。【文档】<code>20-pipeline.md</code> §4.1</li><li>canonical 必须<strong>真的是超集</strong>，否则就会重演 agentgateway 文档里那一长串静默丢弃。这是整套设计最大的可攻击点，<code>00-overview.md</code> §1.1b 专门有一节正面回应。</li><li><strong>35 个可选端口</strong>都要在组合根装配一次；漏接不编译报错，只在运行时静默少一个能力。【代码】<code>composition-root.ts</code> 的 <code>GatewayOptions</code></li><li>每加一种模态 / 格式都要补测试与文档卡片，忘了就是 CI 红灯，不是「以后再补」。</li></ol>",3)),o(c,{kind:"warn",title:"最该先知道的一条现状：设计说废弃的东西，代码里还活着"},{default:r(()=>[...e[0]||(e[0]=[d(" `AGENTS.md`、`20-pipeline.md` §4、`00-overview.md` §4.1 **三处**都写「一律走 canonical，字节级 fast path 已废弃」。但代码里它还活着：`gateway-core/pipeline/fast-path.ts`、`s1-decode.ts` 的 `shallowDecode`、`s4-encode.ts` 里 `if (ctx.fast_path)` 的**原始字节透传分支**、`tests/fast-path.test.ts`、以及 `adaptors/*/codec.test.ts` 里那条「B. 同格式 fast path 字节级透传」。【代码】这不是推断，两边我都读到了。详见 §8 缺口 1。 ",-1)])]),_:1}),e[9]||(e[9]=t("hr",null,null,-1)),e[10]||(e[10]=t("h2",{id:"_2-·-轴一-格式轴-客户端格式-↔-ag-ir-canonical-↔-provider-格式",tabindex:"-1"},[d("2 · 轴一：格式轴（客户端格式 ↔ AG-IR canonical ↔ provider 格式） "),t("a",{class:"header-anchor",href:"#_2-·-轴一-格式轴-客户端格式-↔-ag-ir-canonical-↔-provider-格式","aria-label":'Permalink to "2 · 轴一：格式轴（客户端格式 ↔ AG-IR canonical ↔ provider 格式）"'},"​")],-1)),e[11]||(e[11]=t("p",null,[d("这张图是整个系统的脊柱。"),t("strong",null,"注意中间那个盒子"),d("——它不是某个厂商的格式，是自建的超集。")],-1)),o(I,{"source-b64":""}),e[12]||(e[12]=a('<p><strong>为什么中间不放某个厂商格式</strong>：OpenAI Chat 格式不是真超集——没有 Anthropic 的 <code>cache_control</code> 块级断点、没有 <code>thinking.signature</code>、没有 Gemini 的 <code>thoughtsTokenCount</code>/grounding metadata；而且枢轴格式由单一厂商掌控，它每次改版都迫使网关跟着改。【文档】<code>00-overview.md</code> §1.1</p><p><strong>保真怎么兜</strong>：<code>raw.unmapped</code>（顶层未建模字段）+ 每节点 <code>_raw</code>（原文对象）+ <code>UnknownPart</code>（未知 part 类型降级保留而不是报错）。回写时四级优先级：整体还原 → 逐节点还原 → 顶层 unmapped 回写 → 结构化转换。【文档】<code>10-canonical-schema.md</code> §7</p><details><summary>展开：agentgateway 为什么走相反的路（这是对这套设计最强的反对意见）</summary><p>agentgateway（Rust，LF/AAIF）的做法是<strong>每格式一套强类型 struct + <code>rest</code> 透传 + 两两配对转换</strong>，并且源码注释明确写它的归一化表示「是 observability representation，<strong>不是</strong> lossless wire format」。它的理由是：强行用唯一 IR 承载 wire，会立刻遇到一长串静默丢弃。</p><p>我们仍然选 canonical，因为核心需求不同：<strong>插件要只面对 canonical、usage/finish_reason 要在一处归一、dog-fooding 数据面要统一</strong>——这三件只有 canonical 能满足。agentgateway 的 visitor 方案能让护栏改文本，但护栏看不到「这次请求原本是 Anthropic 格式、带 1h ephemeral cache 断点」，也拿不到统一的 usage。【文档】<code>00-overview.md</code> §1.1b（含五维对照表）</p><p>我们明确借用它四条来弥补风险：typed struct + rest 透传、有序偏好表、token 双轨（归一值 + <code>usage_raw</code>）、wire 层与归一化层的分离意识。</p></details><hr><h2 id="_3-·-轴二-di-轴-接口-构造注入-组合根" tabindex="-1">3 · 轴二：DI 轴（接口 + 构造注入 + 组合根） <a class="header-anchor" href="#_3-·-轴二-di-轴-接口-构造注入-组合根" aria-label="Permalink to &quot;3 · 轴二：DI 轴（接口 + 构造注入 + 组合根）&quot;">​</a></h2><p>这条轴和格式轴<strong>正交</strong>：格式轴管「数据的形状怎么变」，DI 轴管「谁依赖谁」。加一种格式只碰 <code>adaptors/</code> 与 <code>ir/format.ts</code>，不碰组合根的端口清单；加一家 provider 只碰 <code>providers/</code> 与 <code>credentials/</code>，不碰 codec。</p>',6)),o(l,{items:[{key:"接口",value:"di/ports.ts —— Clock / Logger / Metrics / IdGenerator / GatewayConfig / ProviderProfile / ProviderProfileRegistry，每个配一个最小内存实现"},{key:"令牌",value:"di/tokens.ts —— 字符串键 + 泛型 phantom，不引 reflect-metadata，错误在编译期就能看到"},{key:"容器",value:"di/container.ts —— register / registerSingleton / registerValue / createChild；只做登记、解析、循环依赖检测，不做自动装配"},{key:"env 收敛",value:"di/config.ts —— 唯一读 process.env 的地方（另 credentials/resolver.ts 有一处默认参数）"},{key:"组合根",value:"composition-root.ts（1492 行）—— 全仓库唯一「知道所有具体实现」的地方，也是那条禁令的唯一例外"},{key:"测试替身",value:"registerValue 整体替换任一依赖；tests/di.test.ts 覆盖三条架构强制要求"}]}),e[13]||(e[13]=a('<p>【代码】验证过的一件事：除 <code>di/config.ts</code> 与 <code>credentials/resolver.ts:179</code> 的默认参数外，仓库里没有模块直读 <code>process.env</code>——<code>providers/deepseek/profile.ts</code>、<code>discovery.ts</code>、<code>search.ts</code>、<code>providers/openai-images/client.ts</code>、<code>admin/provider-models.ts</code> 里那些匹配项<strong>全在注释里</strong>（原文写着「本文件不读 process.env」）。</p><hr><h2 id="_4-·-「加一种客户端格式」vs「加一家-provider」分别动哪些文件" tabindex="-1">4 · 「加一种客户端格式」vs「加一家 provider」分别动哪些文件 <a class="header-anchor" href="#_4-·-「加一种客户端格式」vs「加一家-provider」分别动哪些文件" aria-label="Permalink to &quot;4 · 「加一种客户端格式」vs「加一家 provider」分别动哪些文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>加一种<strong>客户端格式</strong></th><th>加一家 <strong>provider</strong>（wire 格式已存在）</th></tr></thead><tbody><tr><td>1</td><td><code>ir/format.ts</code>：<code>FormatId</code> 加一个值</td><td><code>credentials/resolver.ts</code>：<code>DEFAULT_ACCESS_PATHS</code> 加一条（id / label / format / model_namespaces / requires_credential）</td></tr><tr><td>2</td><td><code>adaptors/&lt;新格式&gt;/</code>：新 codec，<strong>8 个方法一个不能少也不许多</strong>（decode / encode / decodeResponse / encodeResponse / decodeStream / encodeStream / extractUsage / normalizeFinishReason）</td><td><code>providers/&lt;新厂商&gt;/profile.ts</code>：<code>ProviderProfile</code>（endpointPath / usageFromRaw / builtinToolWire / builtinToolAcceptsConfig / thinkingWire）</td></tr><tr><td>3</td><td><code>adaptors/index.ts</code>：<strong>显式 register</strong>（不做魔法自动发现，否则「哪些 adaptor 真被测过」不可审查）</td><td><code>composition-root.ts</code>：<code>createDefaultProviderProfiles()</code> 注册 profile</td></tr><tr><td>4</td><td><code>http/server.ts</code>：<code>ROUTES</code> 路径签名 → FormatId；<code>s0-ingress.ts</code>：格式识别（header / 路径 / body 嗅探）</td><td><code>providers/presets.ts</code>：管理面「新建渠道」预设（base_url / dialect / default_models / source URL / confidence，拿不准标 <code>needs_verification</code>）</td></tr><tr><td>5</td><td>S2 能力矩阵条目（<code>composition-root.ts</code> <code>defaultCapabilities()</code>）</td><td>能力矩阵条目 + <code>admin/aliases.ts</code> 路由别名（可选）</td></tr><tr><td>6</td><td>usage 口径表（<code>40-provider-adaptors.md</code> §2.1）加一列</td><td><code>metering/pricing.ts</code> + <code>pricing.json</code>：单价（查不到记 <code>pending_price</code> / <code>unpriced</code>，不影响主链路）</td></tr><tr><td>7</td><td><code>adaptors/fixtures/&lt;格式&gt;/</code>：<strong>3–5 份真实样本</strong>（流式 + 非流式、最小 + 最大、含工具调用、含多模态）；「没有样本不动手」</td><td>契约 / 集成测试；fixtures 也要过 privacy-scan</td></tr><tr><td>8</td><td><code>docs/design/10-canonical-schema.md</code> §9：字段映射表补一行或一个子表</td><td><code>docs/design/40-provider-adaptors.md</code> §5：覆盖矩阵三态改一行</td></tr><tr><td>9</td><td><strong>若带来新模态</strong>：<code>ir/&lt;模态&gt;.ts</code> + <code>ir/schema/ag-ir-1/&lt;模态&gt;.schema.json</code> + 夹具 + <code>docs/design/85-modality-surface-matrix.md</code> 建 <code>### 卡片 · &lt;kind&gt;</code></td><td>同左（仅当这家 provider 带来新模态）</td></tr><tr><td>10</td><td>动工前过 <code>40-provider-adaptors.md</code> §1.6 的 <strong>12 项检查清单</strong></td><td>同左 + 一条容易漏的：管理面建了 provider 但没进 <code>DEFAULT_ACCESS_PATHS</code>，「建了渠道」到「能路由」之间缺一环，<strong>且没有任何报错</strong>（<code>credentials/resolver.ts:40</code> 注释原文）</td></tr></tbody></table><p>【文档】关键区分，别混淆两张矩阵：<strong>canonical schema 是全面的（超集），adaptor 是按需写的</strong>。宁可 canonical 里有 adaptor 用不到的字段，也不能出现「某个厂商有办法实现、但 canonical 装不下」。目标是「新增 adaptor 永远不需要改 schema」。</p><hr><h2 id="_5-·-七条不可违背的约束" tabindex="-1">5 · 七条不可违背的约束 <a class="header-anchor" href="#_5-·-七条不可违背的约束" aria-label="Permalink to &quot;5 · 七条不可违背的约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>约束</th><th>是什么</th><th>为什么</th><th>违反了什么会红</th></tr></thead><tbody><tr><td>1</td><td><strong>always-canonical</strong></td><td>v1 每个请求完整 decode → canonical → encode，响应再完整转回；S4/S8 一律由 canonical 重新编码，<strong>不做字节级 fast path</strong></td><td>换来四条：单一代码路径、插件永远可见 canonical、usage 标准化永远执行、round-trip 测试永远被走到（20 §4.1）</td><td><code>adaptors/*/codec.test.ts</code> 的「同格式字节级保真」；<code>RequestContext.canonical_roundtrip</code> 恒 true。⚠️ 但代码里 fast path 仍活着，见 §8 缺口 1</td></tr><tr><td>2</td><td><strong>插件只操作 canonical</strong></td><td>5 个 hook：<code>onRequest</code> / <code>onResponse</code> / <code>onStreamChunk</code> / <code>onError</code> / <code>onToolCall</code>；插件拿不到任何 provider 原始 body，也拿不到 provider 的 HTTP 客户端</td><td>没有现成开源项目提供「格式无关」的插件 hook——LiteLLM / agentgateway 的 hook 都挂在具体协议的字节上（00 §7.2）</td><td><code>tests/plugin-host.test.ts</code>；manifest 不合法<strong>启动即失败</strong>（<code>PluginRegistrationError</code>）；<code>onStreamChunk</code> + <code>context_compaction</code> 同声明 → 注册期校验抛错（<code>ir/plugin.ts:174</code>）</td></tr><tr><td>3</td><td><strong>每种格式互转都要 round-trip 测试</strong></td><td>adaptor 层 6 条（幂等 / 同格式保真 / 未知字段不丢 / 畸形 tool 参数不被销毁 / 多 system 不丢 / 流式事件序列等价）+ <strong>schema 层全覆盖用例</strong>（没有 adaptor 实现它也要有）</td><td>canonical 必须真的是超集，否则重演 agentgateway 列的那串静默丢失；这是「新增 adaptor 不需要改 schema」的回归网</td><td><code>adaptors/openai-chat/codec.test.ts</code> 的 A–E + 流式；<code>tests/ir-schema.test.ts</code> 的 TS↔schema parity</td></tr><tr><td>4</td><td><strong>统计计费独立异步管道</strong></td><td>S10 <code>UsageEmitter</code> → 内存队列 → 批量刷存储；<strong>永不抛异常影响主链路</strong>；队列满按 <code>drop_policy</code>（默认丢弃最旧 + 计数告警）</td><td>计费失败不该让用户请求失败；「未知」绝不用 0 表示，否则看板静默少报</td><td><code>tests/metering.test.ts</code>、<code>tests/usage-sniffer.test.ts</code>（流式 usage 超限时省略该键 + <code>usage_sniffer_truncated</code>，不记 0）</td></tr><tr><td>5</td><td><strong>新增模态必须建 85 号矩阵卡片</strong></td><td><code>ir/modality.ts</code> 的 <code>MODALITY_KINDS</code> 每个值都要在 <code>85-modality-surface-matrix.md</code> 有 <code>### 卡片 · &lt;kind&gt;</code>（canonical payload / 入站脸 / provider adaptor / 计量单位 四列 + 状态 + 缺口）；<strong>反向也不允许</strong>出现类型里不存在的 kind</td><td>卡片是流程的<strong>一等步骤</strong>，不是事后补的文档——忘了建，「这个模态端到端能不能用」就没有答案</td><td><code>scripts/check-docs.mjs</code> 第 5 项 → <code>tests/docs-check.test.ts</code> <strong>三条负向用例</strong>（少一张卡片 / 多一张不存在的卡片 / 加了 modality 忘建卡片）</td></tr><tr><td>6</td><td><strong>数据面默认拒绝 + 显式豁免</strong></td><td><code>isDataPlanePath</code> = <code>/v1/</code> 或 <code>/v1beta/</code> 前缀；没注入鉴权器 = <strong>401</strong>（不是放开）；豁免清单 <code>DATA_PLANE_AUTH_EXEMPTIONS</code> 唯一一条 <code>GET /health</code>，每条必须带 <code>why</code></td><td>新端点只要落在这两个前缀下就被自动覆盖——<strong>不需要每个新增端点记得接线</strong>，忘了接的那天它仍然是关着的</td><td><code>tests/data-plane-deny-first.test.ts</code>；<code>tests/agent-chat-data-plane-auth.test.ts</code>（把同名豁免标记写在数据面请求的头 / body / query 里，一律 401）</td></tr><tr><td>7</td><td><strong>管理面前端 UI 文案纪律</strong></td><td>界面只允许四种文字：字段标签、placeholder、必要的短 Tooltip、错误/成功反馈。<strong>内部术语</strong>（canonical / AG-IR / S0 / pipeline / 透传 / dialect / codec / KEK / DEK / env_ref / access_path / stale …）不许出现在用户可见串里；单串 &gt; 12 字即疑似；豁免必须带理由</td><td>用户不该看见内部术语；整段讲解移 <code>webui/admin/src/pages/Help.tsx</code> 并用 <code>helpHref(&#39;&lt;section&gt;&#39;)</code> 深链指过去</td><td><code>scripts/check-ui-copy.mjs</code> → <code>tests/ui-copy-check.test.ts</code>（含正反向用例）。<strong>没写理由的豁免按错误计</strong>——豁免的意思是「审过并决定留」，不是「别吵」</td></tr></tbody></table><details><summary>展开：约束 6 的两个真实坑（都是修过的，不是纸面规则）</summary><p><strong>坑一 · 忘配凭据 = 谁都能进。</strong> 修复前 <code>auth/data-plane.ts</code> 的模式判定链末梢是「以上都没有 → permissive（不校验任何凭据）」。修法是新增第四档 <code>deny</code>：以上都没配 → <strong>503</strong>（不是 401），理由是「没配凭据是运维问题，不是调用方传错 key」，两者必须可区分。【实测】<code>AUTH-AUDIT-REPORT.md</code> §3.2–3.3：19 个入站脸无凭据全部 401、runner 零调用。</p><p><strong>坑二 · 内置对话打不通自己的数据面。</strong> <code>admin/agent-chat.ts</code> 早先注释写「鉴权头按白名单挡在外面，S0 用不到」，而 S0 的鉴权阶段无条件跑——virtual_key 模式下内置对话整条链路失败在 S0，界面拿到的是「缺少 API key」而不是上游结果。既有 e2e 测试注入的是 permissive 占位鉴权器，所以这一层从来没人真打过。修正后的口径：豁免<strong>代码级、单点定义、<code>key_id</code> 固定归因 <code>agent-builtin</code></strong>，且判据只有 <code>PipelineInput.auth_exemption</code> 这一个类型化字段，线上伪造不了。【文档 + 实测】<code>95-agent-chat.md</code> §9、<code>tests/agent-chat-data-plane-auth.test.ts</code></p></details><details><summary>展开：约束 5 为什么值得一个脚本 + 一个测试文件</summary><p><code>tests/docs-check.test.ts</code> 的存在理由写在它自己的文件头里，值得原样引用：模态卡片硬校验此前<strong>只在文档改动才触发的 CI</strong> 里跑，意味着「加了模态、改了 <code>ir/modality.ts</code>、没碰 docs」这种<strong>最常见的忘记姿势恰好不会触发它</strong>。所以用子进程跑真脚本（不 import、不重实现校验逻辑，逻辑只有一份），让 <code>npm test</code> 也当那条红线，并用临时树证明红线两端（缺卡片 / 多卡片）真的会红——「只跑正向用例的话，脚本坏了但恰好全绿」与「真的全绿」无法区分。【代码】</p></details><hr><h2 id="_6-·-di-的真实代价-这部分请写实读" tabindex="-1">6 · DI 的真实代价（这部分请写实读） <a class="header-anchor" href="#_6-·-di-的真实代价-这部分请写实读" aria-label="Permalink to &quot;6 · DI 的真实代价（这部分请写实读）&quot;">​</a></h2><h3 id="_6-1-机制-每个可选端口都要在组合根装配一次" tabindex="-1">6.1 机制：每个可选端口都要在组合根装配一次 <a class="header-anchor" href="#_6-1-机制-每个可选端口都要在组合根装配一次" aria-label="Permalink to &quot;6.1 机制：每个可选端口都要在组合根装配一次&quot;">​</a></h3><p>【代码】<code>createGateway(options: GatewayOptions)</code> 有 <strong>35 个可选字段</strong>，全部可省；<code>startHttpServer</code> 的 8 个选项里 6 个可选。省掉的后果<strong>不是编译错误</strong>，是运行时静默少一个能力：</p><table tabindex="0"><thead><tr><th>漏接 / 写错</th><th>症状</th><th>会编译报错吗</th><th>证据</th></tr></thead><tbody><tr><td>不传 <code>authenticator</code></td><td>除 <code>/health</code> 外<strong>整个数据面 401</strong></td><td>否</td><td>【实测】<code>AUTH-AUDIT-REPORT.md</code> §3.1：19 个入站脸全 401、runner 零调用</td></tr><tr><td>不传 <code>tools</code></td><td><code>/v1/tools/*</code> 走 <strong>404</strong></td><td>否</td><td>【代码】<code>http/server.ts</code>：<code>if (tools !== undefined &amp;&amp; path.startsWith(TOOLS_PATH_PREFIX))</code></td></tr><tr><td>不传 <code>modalities</code></td><td><code>/v1/images</code>、<code>/v1/embeddings</code>、<code>/v1/decisions</code> 走 404</td><td>否</td><td>【代码】同上形态</td></tr><tr><td>不传 <code>audio</code></td><td><code>/v1/audio/*</code> 走 404</td><td>否</td><td>【代码】同上形态</td></tr><tr><td>不传 <code>usageSink</code>（production 模式）</td><td>usage 进黑洞，管理面看板全空</td><td>否</td><td>【代码】<code>ag-serve.mjs</code> 注释原文：「生产模式不注入 sink 时 usage 会进黑洞」</td></tr><tr><td>不传 <code>startup</code></td><td><strong>界面显示的值和请求路径用的值不一致</strong></td><td>否</td><td>【代码】<code>http/server.ts</code> 注释原文：「『忘了调』的后果是界面显示的值和请求路径用的值不一致，而这种不一致没有任何报错」</td></tr><tr><td><code>modalities</code> 拼成 <code>modality</code></td><td>该端口静默不挂载</td><td><strong>直接传对象字面量时 TS 的 excess-property check 会报错</strong>；经中间变量 / 展开构造时不会</td><td>【推断】见下方说明</td></tr></tbody></table><h3 id="_6-2-部署脚本不在仓库-所以装配正确性零-ci-覆盖" tabindex="-1">6.2 部署脚本不在仓库，所以装配正确性零 CI 覆盖 <a class="header-anchor" href="#_6-2-部署脚本不在仓库-所以装配正确性零-ci-覆盖" aria-label="Permalink to &quot;6.2 部署脚本不在仓库，所以装配正确性零 CI 覆盖&quot;">​</a></h3><p>【代码】<code>ag-serve.mjs</code> 的文件头自称「<strong>本地实跑脚本（临时用，不属于仓库）</strong>」。它注入了 <code>transport</code> / <code>usageSink</code> / <code>recordStore</code> / <code>keystore</code> / <code>adminStaticRoot</code> / <code>adminAccessToken</code> / <code>usageSource</code> / <code>metadataSync</code> / <code>balanceProbe</code>，<code>startHttpServer</code> 那一侧注入了 <code>models</code> / <code>tools</code> / <code>audio</code> / <code>modalities</code> / <code>authenticator</code> / <code>startup</code>——<strong>六个可选端口一个不漏</strong>。问题在于：这份正确性只存在于一份不在仓库、不进 CI、不过 lint 的脚本里。</p><p>【代码】家目录 <code>ai-workspace/</code> 下现存 <strong>4 个变体</strong>（<code>ag-serve.mjs</code> / <code>-28</code> / <code>-32</code> / <code>-wt26</code>）在漂移，其中两个较旧的<strong>没有 <code>authenticator</code></strong>——这正是 <code>AUTH-AUDIT-REPORT.md</code> §3.5 记录的那个缺口，它的结论是「代码侧已保证脚本漏配凭据也不会放行（→ 503），残留风险是若有人照抄一份却写成 <code>mode:&#39;test&#39;</code>，数据面会回到 permissive」。</p>',18)),o(c,{kind:"warn",title:"关于任务描述里点名的两次事故，我要说清楚"},{default:r(()=>[...e[1]||(e[1]=[d(" 描述里说「选项名 `modalities` 写成 `modality`、漏接 `startup` hook，都在 `~/AI-DESKTOP.md` 有记录」。我翻了一遍 `AI-DESKTOP.md`（含 2026-11-15 的 AgentGateway 公网入口那一节）、仓库根全部 `*.md`、`git log`、以及 4 份 `ag-serve` 变体，**没有找到这两次事故的原文记录**。能找到的是：机制（上表）、以及「两个旧变体漏接 `authenticator`」这个同源事实。所以本节只讲机制与可验证的部分；那两次具体事故请当作**未经我核实**处理。 ",-1)])]),_:1}),e[14]||(e[14]=a('<h3 id="_6-3-建议-两条-都不大" tabindex="-1">6.3 建议（两条，都不大） <a class="header-anchor" href="#_6-3-建议-两条-都不大" aria-label="Permalink to &quot;6.3 建议（两条，都不大）&quot;">​</a></h3><ol><li><strong>把 <code>scripts/serve.mjs</code> 收进仓库</strong>——连同它的数据目录约定与 env 清单。收益：至少能 typecheck + lint + privacy-scan 它，变体漂移有了单一出处。</li><li><strong>加一条「所有可选端口都被挂载」的测试</strong>：在测试里跑真 <code>startHttpServer</code>，对每个端口断言一个<strong>可观测行为</strong>——<code>/v1/tools/*</code> 不 404、<code>/health</code> 200、带 virtual key 打数据面 200、启动钩子跑完后设置已应用回 config。这条测试抓住的正是「漏接不编译报错」那一类问题。</li></ol><hr><h2 id="_7-·-一次真实改动的全景-内置对话-ui-移植" tabindex="-1">7 · 一次真实改动的全景：内置对话 UI 移植 <a class="header-anchor" href="#_7-·-一次真实改动的全景-内置对话-ui-移植" aria-label="Permalink to &quot;7 · 一次真实改动的全景：内置对话 UI 移植&quot;">​</a></h2><p>【文档 + 代码】依据 <code>docs/design/96-chat-ui-port.md</code>（已合入，merge commit <code>141f310</code>）。选它当例子是因为它是<strong>最近一次完整走过全流程</strong>的改动，文件清单与检查清单都在纸面上。</p>',5)),o(g,{items:[{title:"定搬什么",body:"七件「纯呈现」搬：thinking 折叠行、工具调用卡、回合过程条、回合用量面板、流光文字、两个格式化 helper、视觉令牌。九件放弃。ChatView 本体与它的 rAF 折叠动画引擎不搬——前者依赖 14 个注入包与一张私有快照，后者依赖 DSH 的滚动锚点与视口驱动。"},{title:"服务端只差一步",body:"AG-IR 早已建模 thinking part，openai.chat codec 也已把 reasoning_content 双向映射；缺的只是 admin/agent-chat.ts 的 foldChat 现在只取 content，把 reasoning_content 丢掉了。取出来即可，不需要新管道。"},{title:"会话管理补读侧",body:"写侧 admin/agent-history.ts 已实现并在 agent_persist_messages 开启时落加密存储，但没有任何路由暴露 list()，前端刷新即失。补 3 个端点 + 记录里一个可选 session_id 字段即可，不需要新存储种类。"},{title:"帧上只加不改",body:"在 95 §6.1 既有五类 SSE 帧上增加三个可选字段，不改帧类型、不改帧序。"},{title:"压冲突面",body:"移植代码全部放进新文件，Chat.tsx 只留 import 与几行 JSX 接线，把与外援 1600 行前端改动的冲突面压到「import 块」。真正要错开的是 §3.5——它与外援改过的 agent 帧 error 字段是相邻行。已确认外援没有动 ToolCallCard / firstLine / RedactedText。"},{title:"过的检查",body:"npm test（agent-chat-e2e / agent-ui-contract / redaction-parity / settings / agent-chat-data-plane-auth 五类）、typecheck:admin、lint、npm run check:ui-copy。"},{title:"谁负责 review",body:"docs/ 改动一律走 PR、由仓库主人 review 后合入，PR 描述写清对应哪个 issue / 哪条 review 意见；代码只提交自己负责范围的文件，git add 用显式路径，不要 git add -A。"}]}),e[15]||(e[15]=a('<p>【实测】<code>AI-DESKTOP.md</code> 2026-11-15 记录：<code>npm test</code> <strong>1548 passed</strong> / <code>typecheck:admin</code> / <code>lint</code> / <code>check:ui-copy</code> 全绿；<code>AUTH-AUDIT-REPORT.md</code> 记录的基数是 <strong>1555 passed / 22 skipped</strong>。</p><details><summary>展开：如果是「接入一家新 provider」（如 MiMo 这类 OpenAI 兼容上游），清单长这样</summary><p>按 §4 右列落地，顺序是：</p><ol><li><code>credentials/resolver.ts</code> 的 <code>DEFAULT_ACCESS_PATHS</code> 加一条。同一家多个 dialect 就加多条（DeepSeek 的先例：OpenAI 兼容面与 Anthropic 兼容面各一条，端点路径差异由 profile 的 <code>endpointPath</code> 表达，<strong>不靠 base URL 拼魔法后缀</strong>）。</li><li><code>providers/&lt;name&gt;/profile.ts</code> 写 <code>ProviderProfile</code>。DeepSeek 的先例说明这文件非写不可：它的 OpenAI 兼容面是 <code>POST /chat/completions</code>（<strong>没有 /v1</strong>）、<code>prompt_cache_hit_tokens</code> 是 usage 顶层字段（OpenAI 系埋在 <code>prompt_tokens_details.cached_tokens</code>）、<code>thinking</code> 是对象开关且<strong>省略时默认开启</strong>（与 canonical 的 <code>enabled</code> 语义相反，不显式表达就会被上游默认值吞掉）。</li><li><code>composition-root.ts</code>：<code>createDefaultProviderProfiles()</code> 注册 + <code>defaultCapabilities()</code> 加能力矩阵条目。</li><li><code>providers/presets.ts</code>：管理面「新建渠道」预设，每条带 <code>source</code>（官方文档 URL）与 <code>confidence</code>，拿不准标 <code>needs_verification: true</code>，UI 显示「待验证」。<strong>不编造 base_url。</strong></li><li><code>metering/pricing.ts</code> + <code>pricing.json</code>：单价。查不到价格的模型记 <code>pending_price</code> / <code>unpriced</code>，不影响主链路。</li><li>若它的 wire 不是 <code>openai.chat</code> / <code>anthropic.messages</code> → 回到 §4 左列的完整清单（那就是「加一种格式」）。</li><li>动工前过 <code>40-provider-adaptors.md</code> §1.6 的 12 项检查清单；fixtures 也要过 privacy-scan。</li><li>别忘了第 10 行那条：管理面能建 provider ≠ 能路由，<code>DEFAULT_ACCESS_PATHS</code> 里没有它就没有任何报错。</li></ol><p>【推断】「MiMo」这个具体名字在仓库里没有任何记录（我搜过 <code>*.md</code> 与 <code>*.ts</code>），所以上面是按 DeepSeek 的真实足迹反推的通用清单，不是 MiMo 的既有方案。</p></details><hr><h2 id="_8-·-现状与缺口" tabindex="-1">8 · 现状与缺口 <a class="header-anchor" href="#_8-·-现状与缺口" aria-label="Permalink to &quot;8 · 现状与缺口&quot;">​</a></h2><h3 id="_8-1-哪些是实的-代码可验证" tabindex="-1">8.1 哪些是实的（代码可验证） <a class="header-anchor" href="#_8-1-哪些是实的-代码可验证" aria-label="Permalink to &quot;8.1 哪些是实的（代码可验证）&quot;">​</a></h3><ul><li><strong>2 个 chat adaptor 已注册并契约测试</strong>：<code>adaptors/index.ts</code> 只注册 <code>openai.chat</code> 与 <code>anthropic.messages</code>，注释明说「没实现的 adaptor 注册进来只会制造『看起来支持』的假象」。【代码】</li><li><strong>9 个模态的 canonical payload 都在 <code>ir/</code></strong>；四件套齐的是 chat / decision / embedding / image，工具面（search / fetch / ocr / asr / tts）齐且接<strong>真实 DeepSeek 上游</strong>。【文档】<code>85-modality-surface-matrix.md</code> §3</li><li><strong>DI 容器 + 组合根在位</strong>，测试可整体替换任一依赖；env 读取基本收敛在 <code>di/config.ts</code>。【代码】</li><li><strong>数据面默认拒绝 + 纵深</strong>：tools / audio / modalities 三个注入端口在 <code>handle()</code> 内部<strong>各自再过一次</strong>同一个 <code>DataPlaneAuthenticator</code>——即使传输层的门接错，这些脸仍然拒。【实测】<code>AUTH-AUDIT-REPORT.md</code> §4 测试 D</li><li><strong>UI 文案纪律与 85 矩阵硬校验都已进 <code>npm test</code></strong>，不只是文档 CI。【代码】</li><li><strong>三张矩阵分工明确且互相不替代</strong>：canonical 覆盖矩阵答「schema 装不装得下」，adaptor 覆盖矩阵答「某家映射写没写」，模态覆盖矩阵答「这个模态四件套齐不齐、能不能端到端用」。【文档】<code>85</code> §1.1</li></ul><h3 id="_8-2-哪些还欠着" tabindex="-1">8.2 哪些还欠着 <a class="header-anchor" href="#_8-2-哪些还欠着" aria-label="Permalink to &quot;8.2 哪些还欠着&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>缺口</th><th>性质</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td><strong>字节级 fast path：文档说废弃，代码还活着</strong></td><td>方向性分歧，需拍板</td><td><code>gateway-core/pipeline/fast-path.ts</code>、<code>s1-decode.ts</code> 的 <code>shallowDecode</code>、<code>s4-encode.ts</code> 的 <code>ctx.fast_path</code> 透传分支、<code>tests/fast-path.test.ts</code>、<code>adaptors/*/codec.test.ts</code> 的「同格式 fast path 字节级透传」、<code>UsageRecord.fast_path</code> / <code>route.fast_path_eligible</code> 字段、WebUI 类型里的 <code>fast_path</code>——全都在。要么删代码，要么改文档，不能两边各说一套。【代码】</td></tr><tr><td>2</td><td><strong>部署脚本不在仓库</strong></td><td>装配正确性零覆盖</td><td>4 个变体在漂移，两个旧的漏接 <code>authenticator</code>。建议 §6.3 两条。</td></tr><tr><td>3</td><td><strong>adaptor 覆盖落后于文档口径</strong></td><td>文档与代码不一致</td><td><code>00-overview.md</code> §2.1 与 <code>40-provider-adaptors.md</code> §5 写「3 个 chat adaptor 写透（含 <code>openai.responses</code>）」，<code>adaptors/index.ts</code> 只注册 2 个；<code>85</code> §3.1 与代码一致（标 planned）。以代码与 85 为准。【代码】</td></tr><tr><td>4</td><td><strong>真实上游只有 DeepSeek 一家</strong></td><td>范围</td><td>image / embedding / decision 都卡在无 key 或 mock。<code>85</code> §5.1 的 P0 写得很直白：「真实图片上游……卡在无 key，阻塞项是凭据不是代码」。</td></tr><tr><td>5</td><td><strong>tts / asr 只有工具面，缺 schema 层兜底</strong></td><td>覆盖缺口</td><td>现在走工具面 canonical（<code>CanonicalToolRequest</code>），<code>ir/schema/ag-ir-1/</code> 里没有 <code>tts.schema.json</code> / <code>asr.schema.json</code>，夹具也没有——canonical 覆盖矩阵登记的 TTS/ASR 特性目前<strong>没有</strong> schema 层 round-trip 用例兜底（<code>12</code> §3 规则 F6 要求「没有 adaptor 实现它也要有这条用例」）。【文档】<code>85</code> §5.2</td></tr><tr><td>6</td><td><strong>文档同步欠账</strong></td><td>文档</td><td><code>85</code> §6.3 列了 7 条待更新（端点表、FormatId 清单、ImagePayload 加法、40 §5 三态…）。另：<code>AGENTS.md</code> 开头「当前状态：WIP，只有定位说明与骨架，<strong>尚无可用代码</strong>」已明显过期——同期 <code>AI-DESKTOP.md</code> 记录 <code>npm test</code> 1548 passed。【代码 + 实测】</td></tr><tr><td>7</td><td><strong>三张矩阵最容易被读错</strong></td><td>认知风险</td><td>「canonical 装得下」≠「adaptor 写了」≠「端到端能用」。读者最容易把第一张当成第三张，然后以为某个模态已经可以上线。</td></tr></tbody></table><hr><h2 id="_9-·-深挖指路" tabindex="-1">9 · 深挖指路 <a class="header-anchor" href="#_9-·-深挖指路" aria-label="Permalink to &quot;9 · 深挖指路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想知道</th><th>去读</th></tr></thead><tbody><tr><td>模块划分的唯一事实来源、术语表</td><td><code>docs/design/00-overview.md</code> §4.2、§5</td></tr><tr><td>canonical 长什么样、raw passthrough 怎么回写</td><td><code>docs/design/10-canonical-schema.md</code> §2、§7、§9</td></tr><tr><td>11 个阶段各自干什么、fast path 废弃理由与加回条件</td><td><code>docs/design/20-pipeline.md</code> §2、§4</td></tr><tr><td>新增 adaptor 的机械步骤、round-trip 测试模板、12 项检查清单</td><td><code>docs/design/40-provider-adaptors.md</code> §1.0–1.6</td></tr><tr><td>「模态完成」判据与硬校验规则</td><td><code>docs/design/85-modality-surface-matrix.md</code> §2</td></tr><tr><td>内置对话与 Agent 管理的三条硬约束</td><td><code>docs/design/95-agent-chat.md</code> §1.3</td></tr><tr><td>对话 UI 移植的搬/不搬清单与冲突面</td><td><code>docs/design/96-chat-ui-port.md</code> §0.1、§2、§7</td></tr><tr><td>协作约定、UI 文案纪律、提交规范</td><td>仓库根 <code>AGENTS.md</code></td></tr><tr><td>deny-first 的实测矩阵与豁免清单</td><td>仓库根 <code>AUTH-AUDIT-REPORT.md</code></td></tr><tr><td>部署链路与踩坑（含 8888 公网入口实测）</td><td><code>~/AI-DESKTOP.md</code> 的 AgentGateway 一节</td></tr></tbody></table>',11)),o(c,{kind:"tip",title:"这个页面讲了什么（五句）"},{default:r(()=>[...e[2]||(e[2]=[d(" ① AgentGateway 的解耦是两条正交的轴：格式轴（客户端格式 ↔ 自建 AG-IR canonical ↔ provider 格式）与依赖轴（接口 + 构造注入 + 单一组合根）。② 换来的是「加一种格式 / 一家 provider 是机械活」，代价是每请求完整走 canonical、canonical 必须真是超集、35 个可选端口都要手工装配。③ 有七条不可违背的约束，每条都有对应的红灯测试或脚本，不是纸面规矩。④ DI 最实的痛点是部署脚本不在仓库——漏接端口不编译报错，只在运行时静默少能力。⑤ 最大的现存缺口是：设计文档三处说字节级 fast path 已废弃，代码里它还活着，需要拍板。 ",-1)])]),_:1})])}const j=p(u,[["render",S]]);export{y as __pageData,j as default};
